I'll create a Pulumi ComponentResource that wraps an S3 bucket, RDS PostgreSQL, and IAM role with environment-aware configuration.

## Project Structure

```
.
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
├── appService.ts
├── config.ts
├── package.json
└── tsconfig.json
```

## `Pulumi.yaml`

```yaml
name: app-service-component
runtime: nodejs
description: ComponentResource wrapping S3 + RDS + IAM
```

## `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  app-service-component:environment: dev
  app-service-component:dbInstanceClass: db.t3.micro
  app-service-component:multiAz: false
  app-service-component:backupRetentionDays: "7"
  # Secret: encrypted at rest by Pulumi (never plaintext in Git)
  app-service-component:dbPassword:
    secure: v1:PLACEHOLDER_DEV:encryptedvalue==
```

> Set the secret via: `pulumi config set --secret dbPassword <value>`

## `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  app-service-component:environment: prod
  app-service-component:dbInstanceClass: db.t3.medium
  app-service-component:multiAz: true
  app-service-component:backupRetentionDays: "14"
  app-service-component:replicationRegion: us-west-2
  app-service-component:dbPassword:
    secure: v1:PLACEHOLDER_PROD:encryptedvalue==
```

## `config.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";

export interface AppConfig {
    environment: "dev" | "prod";
    dbInstanceClass: string;
    multiAz: boolean;
    backupRetentionDays: number;
    replicationRegion?: string;
    dbPassword: pulumi.Output<string>;
}

export function loadConfig(): AppConfig {
    const cfg = new pulumi.Config();

    const environment = cfg.require("environment") as "dev" | "prod";
    if (environment !== "dev" && environment !== "prod") {
        throw new Error(`Invalid environment: ${environment}`);
    }

    const backupRetentionDays = cfg.requireNumber("backupRetentionDays");
    if (backupRetentionDays < 7) {
        throw new Error("backupRetentionDays must be >= 7 (acceptance criteria)");
    }

    return {
        environment,
        dbInstanceClass: cfg.require("dbInstanceClass"),
        multiAz: cfg.requireBoolean("multiAz"),
        backupRetentionDays,
        replicationRegion: cfg.get("replicationRegion"),
        // pulumi secret => encrypted at rest, never plaintext in Git
        dbPassword: cfg.requireSecret("dbPassword"),
    };
}
```

## `appService.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppServiceArgs {
    environment: "dev" | "prod";
    dbInstanceClass: string;
    multiAz: boolean;
    backupRetentionDays: number;
    dbPassword: pulumi.Input<string>;
    /** Enable cross-region replication (prod). */
    replicationRegion?: string;
    /** OIDC provider ARN for least-privilege IRSA role (prod). */
    oidcProviderArn?: pulumi.Input<string>;
    /** Optional VPC subnet ids for the RDS subnet group. */
    subnetIds?: pulumi.Input<string>[];
    tags?: Record<string, string>;
}

/**
 * AppService bundles the supporting infrastructure for a stateless web app:
 *   - S3 bucket (versioned, encrypted, private)
 *   - RDS PostgreSQL (deletion protection, backups, not public)
 *   - IAM role for the service account (least privilege)
 */
export class AppService extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbConnectionString: pulumi.Output<string>;
    public readonly serviceRoleArn: pulumi.Output<string>;

    constructor(
        name: string,
        args: AppServiceArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("app:infra:AppService", name, {}, opts);

        const isProd = args.environment === "prod";
        const baseTags = {
            Environment: args.environment,
            ManagedBy: "pulumi",
            Component: "AppService",
            ...args.tags,
        };
        const child = { parent: this };

        // ------------------------------------------------------------------
        // KMS key (used for prod S3 + RDS encryption)
        // ------------------------------------------------------------------
        const kmsKey = new aws.kms.Key(`${name}-kms`, {
            description: `Encryption key for ${name} (${args.environment})`,
            enableKeyRotation: true,
            deletionWindowInDays: isProd ? 30 : 7,
            tags: baseTags,
        }, child);

        // ==================================================================
        // 1. S3 BUCKET — versioned, encrypted, private
        // ==================================================================
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            tags: baseTags,
        }, {
            ...child,
            // prod bucket has deletion protection semantics
            protect: isProd,
        });

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, child);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: bucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: isProd
                        ? { sseAlgorithm: "aws:kms", kmsMasterKeyId: kmsKey.arn }
                        : { sseAlgorithm: "AES256" },
                    bucketKeyEnabled: isProd,
                }],
            },
            child,
        );

        // Block ALL public access
        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, child);

        // ------------------------------------------------------------------
        // Cross-region replication (prod only)
        // ------------------------------------------------------------------
        if (isProd && args.replicationRegion) {
            this.setupReplication(name, bucket, args.replicationRegion, baseTags, child);
        }

        // ==================================================================
        // 2. RDS POSTGRESQL — deletion protection, backups, private
        // ==================================================================
        const dbSg = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            description: `RDS access for ${name}`,
            // No ingress from 0.0.0.0/0 — kept private; VPC-internal only.
            egress: [{
                protocol: "-1",
                fromPort: 0,
                toPort: 0,
                cidrBlocks: ["0.0.0.0/0"],
            }],
            tags: baseTags,
        }, child);

        let subnetGroupArgs: pulumi.ComponentResourceOptions & { subnetGroupName?: pulumi.Output<string> } = {};
        let dbSubnetGroupName: pulumi.Output<string> | undefined;
        if (args.subnetIds && args.subnetIds.length > 0) {
            const subnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
                subnetIds: args.subnetIds,
                tags: baseTags,
            }, child);
            dbSubnetGroupName = subnetGroup.name;
        }

        const db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "15",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: isProd ? 100 : 20,
            maxAllocatedStorage: isProd ? 500 : 100,

            dbName: "appdb",
            username: "appuser",
            password: args.dbPassword,

            // --- Acceptance criteria ---
            deletionProtection: true,
            backupRetentionPeriod: args.backupRetentionDays,
            publiclyAccessible: false,
            storageEncrypted: true,
            kmsKeyId: isProd ? kmsKey.arn : undefined,
            multiAz: args.multiAz,

            backupWindow: "03:00-04:00",
            maintenanceWindow: "mon:04:00-mon:05:00",
            vpcSecurityGroupIds: [dbSg.id],
            dbSubnetGroupName: dbSubnetGroupName,

            skipFinalSnapshot: !isProd,
            finalSnapshotIdentifier: isProd
                ? `${name}-final-snapshot`
                : undefined,
            applyImmediately: !isProd,

            enabledCloudwatchLogsExports: ["postgresql"],
            tags: baseTags,
        }, {
            ...child,
            protect: isProd,
        });

        // ==================================================================
        // 3. IAM ROLE — least privilege for the service account
        // ==================================================================
        // Trust policy: OIDC (IRSA) in prod, EC2 assume in dev.
        const assumeRolePolicy: pulumi.Output<string> = isProd && args.oidcProviderArn
            ? pulumi.output(args.oidcProviderArn).apply((arn) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: arn },
                        Action: "sts:AssumeRoleWithWebIdentity",
                    }],
                }))
            : pulumi.output(JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            }));

        const serviceRole = new aws.iam.Role(`${name}-svc-role`, {
            assumeRolePolicy,
            tags: baseTags,
        }, child);

        // Least-privilege inline policy scoped to THIS bucket + KMS key.
        // No wildcard actions in prod.
        const s3Actions = isProd
            ? ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
            : ["s3:GetObject", "s3:PutObject", "s3:ListBucket"];

        const policyDoc = pulumi
            .all([bucket.arn, kmsKey.arn])
            .apply(([bucketArn, keyArn]) => {
                const statements: any[] = [
                    {
                        Sid: "BucketObjectAccess",
                        Effect: "Allow",
                        Action: s3Actions,
                        Resource: [bucketArn, `${bucketArn}/*`],
                    },
                ];
                if (isProd) {
                    statements.push({
                        Sid: "KmsForBucket",
                        Effect: "Allow",
                        Action: [
                            "kms:Decrypt",
                            "kms:Encrypt",
                            "kms:GenerateDataKey",
                        ],
                        Resource: keyArn,
                    });
                }
                return JSON.stringify({ Version: "2012-10-17", Statement: statements });
            });

        new aws.iam.RolePolicy(`${name}-svc-policy`, {
            role: serviceRole.id,
            policy: policyDoc,
        }, child);

        // ------------------------------------------------------------------
        // Outputs
        // ------------------------------------------------------------------
        this.bucketName = bucket.id;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.endpoint;
        this.serviceRoleArn = serviceRole.arn;

        // Connection string is a secret (composed of a secret password).
        this.dbConnectionString = pulumi
            .all([db.username, args.dbPassword, db.endpoint, db.dbName])
            .apply(([u, p, e, name]) =>
                pulumi.secret(`postgresql://${u}:${p}@${e}/${name}`),
            ) as unknown as pulumi.Output<string>;

        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            dbEndpoint: this.dbEndpoint,
            serviceRoleArn: this.serviceRoleArn,
        });
    }

    /** Configure cross-region replication for the prod bucket. */
    private setupReplication(
        name: string,
        srcBucket: aws.s3.BucketV2,
        region: string,
        tags: Record<string, string>,
        opts: pulumi.ComponentResourceOptions,
    ) {
        const replicaProvider = new aws.Provider(`${name}-replica-provider`, {
            region: region as aws.Region,
        }, opts);
        const replicaOpts = { ...opts, provider: replicaProvider };

        const replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
            tags,
        }, { ...replicaOpts, protect: true });

        new aws.s3.BucketVersioningV2(`${name}-replica-versioning`, {
            bucket: replicaBucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, replicaOpts);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-replica-encryption`,
            {
                bucket: replicaBucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
                }],
            },
            replicaOpts,
        );

        new aws.s3.BucketPublicAccessBlock(`${name}-replica-pab`, {
            bucket: replicaBucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, replicaOpts);

        // Replication role
        const replRole = new aws.iam.Role(`${name}-repl-role`, {
            assumeRolePolicy: JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "s3.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            }),
            tags,
        }, opts);

        const replPolicy = pulumi
            .all([srcBucket.arn, replicaBucket.arn])
            .apply(([srcArn, dstArn]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Action: [
                                "s3:GetReplicationConfiguration",
                                "s3:ListBucket",
                            ],
                            Resource: [srcArn],
                        },
                        {
                            Effect: "Allow",
                            Action: [
                                "s3:GetObjectVersionForReplication",
                                "s3:GetObjectVersionAcl",
                                "s3:GetObjectVersionTagging",
                            ],
                            Resource: [`${srcArn}/*`],
                        },
                        {
                            Effect: "Allow",
                            Action: [
                                "s3:ReplicateObject",
                                "s3:ReplicateDelete",
                                "s3:ReplicateTags",
                            ],
                            Resource: [`${dstArn}/*`],
                        },
                    ],
                }),
            );

        new aws.iam.RolePolicy(`${name}-repl-policy`, {
            role: replRole.id,
            policy: replPolicy,
        }, opts);

        // Replication config must be applied to the SOURCE bucket.
        new aws.s3.BucketReplicationConfig(`${name}-repl-config`, {
            role: replRole.arn,
            bucket: srcBucket.id,
            rules: [{
                id: "replicate-all",
                status: "Enabled",
                priority: 1,
                deleteMarkerReplication: { status: "Enabled" },
                filter: {},
                destination: {
                    bucket: replicaBucket.arn,
                    storageClass: "STANDARD",
                },
            }],
        }, opts);
    }
}
```

## `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AppService } from "./appService";
import { loadConfig } from "./config";

const cfg = loadConfig();

const app = new AppService("webapp", {
    environment: cfg.environment,
    dbInstanceClass: cfg.dbInstanceClass,
    multiAz: cfg.multiAz,
    backupRetentionDays: cfg.backupRetentionDays,
    dbPassword: cfg.dbPassword,
    replicationRegion: cfg.replicationRegion,
    // Pass an OIDC provider ARN here in prod for IRSA:
    // oidcProviderArn: eksCluster.core.oidcProvider!.arn,
    tags: { Project: "canonical-scenario" },
});

// Non-secret outputs
export const bucketName = app.bucketName;
export const bucketArn = app.bucketArn;
export const dbEndpoint = app.dbEndpoint;
export const serviceRoleArn = app.serviceRoleArn;

// Secret output — masked in CLI, encrypted in state
export const dbConnectionString = app.dbConnectionString;
```

